"use client";

import * as React from "react";
import { Cancel01Icon } from "@hugeicons/core-free-icons";
import { Icon } from "./dialog-utils/icon";
import { useScrollEdges } from "./dialog-utils/use-scroll-edges";

export interface DialogProps extends Omit<
  React.DialogHTMLAttributes<HTMLDialogElement>,
  "open" | "title" | "onClose" | "onClick" | "onPointerDown"
> {
  /** Controls whether the dialog is shown. */
  open?: boolean;
  /** Called when the dialog's open state should change (Escape, backdrop press, or the close button). */
  onOpenChange?: (open: boolean) => void;
  title: string;
  description?: string;
  /** Accessible name of the close button; translate it for non-English UIs. */
  closeLabel?: string;
  /** center: modal in the middle. start / end: full-height sheet sliding in from that edge. */
  side?: "center" | "start" | "end";
  /** false: no close button, and a press on the backdrop doesn't close it (confirmations). */
  dismissible?: boolean;
  children?: React.ReactNode;
  footer?: React.ReactNode;
  className?: string;
  onClose?: (e: React.SyntheticEvent<HTMLDialogElement>) => void;
  onClick?: React.MouseEventHandler<HTMLDialogElement>;
  onPointerDown?: React.PointerEventHandler<HTMLDialogElement>;
}

export default function Dialog({
  open = false,
  onOpenChange,
  title,
  description,
  closeLabel = "Close",
  side = "center",
  dismissible = true,
  children,
  footer,
  className,
  onClose,
  onClick,
  onPointerDown,
  ...rest
}: DialogProps) {
  const dialogRef = React.useRef<HTMLDialogElement>(null);
  const pressedBackdropRef = React.useRef(false);
  const reactId = React.useId();
  const id = reactId.replace(/:/g, "");

  useScrollEdges(dialogRef);

  // showModal() gives focus trap, inert page, Escape and focus return for free.
  React.useEffect(() => {
    const dialog = dialogRef.current;
    if (!dialog) return;
    if (open && !dialog.open) {
      dialog.showModal();
      // Start on the dialog itself, so its title is read first, not "Close, button" (React Aria);
      // unless something inside asks for focus (a confirmation's safe choice).
      if (!dialog.querySelector("[autofocus]")) dialog.focus();
    } else if (!open && dialog.open) {
      dialog.close();
    }
  }, [open]);

  return (
    <dialog
      ref={dialogRef}
      tabIndex={-1}
      className={[
        "dialog",
        side !== "center" && "sheet",
        side === "end" && "end",
        className,
      ]
        .filter(Boolean)
        .join(" ")}
      aria-labelledby={`${id}-title`}
      aria-describedby={description ? `${id}-desc` : undefined}
      data-fade-over=""
      {...rest}
      onClose={(e) => {
        onOpenChange?.(false);
        onClose?.(e);
      }}
      onPointerDown={(e) => {
        // Only a press that starts and ends on the backdrop closes: text-selection drags don't.
        pressedBackdropRef.current = e.target === dialogRef.current;
        onPointerDown?.(e);
      }}
      onClick={(e) => {
        if (
          dismissible &&
          pressedBackdropRef.current &&
          e.target === dialogRef.current
        ) {
          dialogRef.current?.close();
        }
        onClick?.(e);
      }}
    >
      <div className="body">
        <header>
          <h2 id={`${id}-title`}>{title}</h2>
          {dismissible && (
            <button
              type="button"
              className="close"
              aria-label={closeLabel}
              onClick={() => dialogRef.current?.close()}
            >
              <Icon icon={Cancel01Icon as any} />
            </button>
          )}
        </header>
        {description && (
          <p id={`${id}-desc`} className="desc">
            {description}
          </p>
        )}
        {children}
        {footer && <footer>{footer}</footer>}
      </div>
    </dialog>
  );
}
